{"command":"cat > src/bounds.rs <<'RS'
// Parsing and representation of user supplied bounds such as `1`, `-2:4`
// or formatted strings such as `({1}, {2})`.

pub const LOC_EMPTY_LIST: &str = "src/bounds/userboundslist.rs:50:14";
pub const LOC_SIDE: &str = "src/bounds/side.rs:108:57";
pub const MSG_EMPTY_LIST: &str = "UserBoundsList must contain at least one UserBounds";

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Side {
    // Positive, 1-based from the start. Always > 0.
    Start(i64),
    // Negative index, stored as its positive magnitude. Always > 0.
    End(i64),
}

impl Side {
    pub fn signed(&self) -> i64 {
        match *self {
            Side::Start(v) => v,
            Side::End(v) => -v,
        }
    }
    pub fn resolve(&self, n: usize) -> i128 {
        match *self {
            Side::Start(v) => v as i128,
            Side::End(v) => n as i128 - v as i128 + 1,
        }
    }
    pub fn display(&self) -> String {
        match *self {
            Side::Start(v) => v.to_string(),
            Side::End(v) => format!("-{v}"),
        }
    }
    pub fn is_end(&self) -> bool {
        matches!(self, Side::End(_))
    }
}

#[derive(Clone, Debug)]
pub enum BoundKind {
    Single(Side),
    // Left: None means 1. Right: None means open ended.
    Range(Option<Side>, Option<Side>),
}

#[derive(Clone, Debug)]
pub struct UserBound {
    pub kind: BoundKind,
    pub fallback: Option<String>,
}

impl UserBound {
    pub fn fallback_bytes(&self) -> Option<&[u8]> {
        self.fallback.as_ref().map(|s| s.as_bytes())
    }
    pub fn display(&self) -> String {
        match &self.kind {
            BoundKind::Single(s) => s.display(),
            BoundKind::Range(l, r) => format!(
                "{}:{}",
                l.as_ref().map_or_else(|| "1".to_string(), |s| s.display()),
                r.as_ref().map_or_else(String::new, |s| s.display())
            ),
        }
    }
    /// (start, end) as resolved symbolic values, with end = i128::MAX for
    /// an open range. Sides are returned as raw signed values.
    pub fn start_end_raw(&self) -> (i128, i128) {
        match &self.kind {
            BoundKind::Single(s) => {
                let v = s.signed() as i128;
                (v, v)
            }
            BoundKind::Range(l, r) => {
                let start = l.as_ref().map_or(1, |s| s.signed() as i128);
                let end = r.as_ref().map_or(i128::MAX, |s| s.signed() as i128);
                (start, end)
            }
        }
    }
    pub fn has_negative_side(&self) -> bool {
        match &self.kind {
            BoundKind::Single(s) => s.is_end(),
            BoundKind::Range(l, r) => {
                l.as_ref().map_or(false, |s| s.is_end()) || r.as_ref().map_or(false, |s| s.is_end())
            }
        }
    }
    pub fn is_point_range(&self) -> bool {
        match &self.kind {
            BoundKind::Range(Some(l), Some(r)) => l.signed() == r.signed(),
            _ => false,
        }
    }
}

#[derive(Clone, Debug)]
pub struct FlatBound {
    pub bound: UserBound,
    // Literal text that precedes this bound in a formatted bounds string.
    pub prefix: Vec<u8>,
}

#[derive(Clone, Debug)]
pub struct BoundsList {
    pub flat: Vec<FlatBound>,
    pub trailing: Vec<u8>,
    // True when the bounds string contained literal text outside of the
    // {..} placeholders (i.e. it is a real format string).
    pub formatted: bool,
}

fn parse_side(s: &str) -> Result<Side, String> {
    let v: i64 = s
        .parse::<i64>()
        .map_err(|_| format!("Not a number `{s}`"))?;
    if v == 0 {
        return Err("Zero is not a valid field".to_string());
    }
    if v == i64::MIN {
        crate::panic_abort(
            LOC_SIDE,
            "called `Result::unwrap()` on an `Err` value: TryFromIntError(())",
        );
    }
    if v > 0 {
        Ok(Side::Start(v))
    } else {
        Ok(Side::End(-v))
    }
}

fn parse_user_bound(item: &str) -> Result<UserBound, String> {
    if item.is_empty() {
        return Err("Field format error: empty field".to_string());
    }
    let (spec, fallback) = match item.find('=') {
        Some(i) => (&item[..i], Some(item[i + 1..].to_string())),
        None => (item, None),
    };
    if let Some(colon) = spec.find(':') {
        let ls = &spec[..colon];
        let rs = &spec[colon + 1..];
        if ls.is_empty() && rs.is_empty() {
            return Err("Field format error, no numbers next to `:`".to_string());
        }
        let left = if ls.is_empty() {
            None
        } else {
            Some(parse_side(ls)?)
        };
        let right = if rs.is_empty() {
            None
        } else {
            Some(parse_side(rs)?)
        };
        if let (Some(l), Some(r)) = (&left, &right) {
            let (lv, rv) = (l.signed(), r.signed());
            if (lv > 0 && rv > 0 && lv > rv) || (lv < 0 && rv < 0 && lv > rv) {
                return Err("Field left value cannot be greater than right value".to_string());
            }
        }
        Ok(UserBound {
            kind: BoundKind::Range(left, right),
            fallback,
        })
    } else if spec.is_empty() {
        Ok(UserBound {
            kind: BoundKind::Single(Side::Start(1)),
            fallback,
        })
    } else {
        Ok(UserBound {
            kind: BoundKind::Single(parse_side(spec)?),
            fallback,
        })
    }
}

fn parse_plain_list(s: &str, top_level: bool) -> Result<Vec<UserBound>, String> {
    if top_level && s.is_empty() {
        return Err("UserBoundsList must contain at least one UserBounds".to_string());
    }
    let mut out = Vec::new();
    for item in s.split(',') {
        out.push(parse_user_bound(item)?);
    }
    Ok(out)
}

fn unescape_braces(content: &str) -> String {
    let mut out = String::new();
    let mut chars = content.chars().peekable();
    while let Some(c) = chars.next() {
        if (c == '{' || c == '}') && chars.peek() == Some(&c) {
            chars.next();
        }
        out.push(c);
    }
    out
}

impl BoundsList {
    pub fn parse(s: &str) -> Result<Self, String> {
        if s.contains('{') || s.contains('}') {
            Self::parse_format(s)
        } else {
            let bounds = parse_plain_list(s, true)?;
            Ok(BoundsList {
                flat: bounds
                    .into_iter()
                    .map(|b| FlatBound {
                        bound: b,
                        prefix: Vec::new(),
                    })
                    .collect(),
                trailing: Vec::new(),
                formatted: false,
            })
        }
    }

    fn parse_format(s: &str) -> Result<Self, String> {
        let chars: Vec<char> = s.chars().collect();
        let mut flat: Vec<FlatBound> = Vec::new();
        let mut lit = String::new();
        let mut content = String::new();
        let mut inside = false;
        let mut i = 0usize;
        while i < chars.len() {
            let c = chars[i];
            let next = chars.get(i + 1).copied();
            if !inside {
                if c == '{' {
                    if next == Some('{') {
                        lit.push('{');
                        i += 2;
                    } else {
                        inside = true;
                        content.clear();
                        i += 1;
                    }
                } else if c == '}' {
                    if next == Some('}') {
                        lit.push('}');
                        i += 2;
                    } else {
                        return Err(
                            "Field format error: missing opening parenthesis".to_string()
                        );
                    }
                } else {
                    lit.push(c);
                    i += 1;
                }
            } else if c == '{' {
                if next == Some('{') {
                    content.push_str("{{");
                    i += 2;
                } else {
                    // A new opening brace while one is pending: the pending
                    // text becomes literal output and a new placeholder
                    // starts here.
                    lit.push_str(&unescape_braces(&content));
                    content.clear();
                    i += 1;
                }
            } else if c == '}' {
                if next == Some('}') {
                    content.push_str("}}");
                    i += 2;
                } else {
                    let bounds = parse_plain_list(&content, false)?;
                    for (j, b) in bounds.into_iter().enumerate() {
                        let prefix = if j == 0 {
                            std::mem::take(&mut lit).into_bytes()
                        } else {
                            Vec::new()
                        };
                        flat.push(FlatBound { bound: b, prefix });
                    }
                    inside = false;
                    content.clear();
                    i += 1;
                }
            } else {
                content.push(c);
                i += 1;
            }
        }
        if inside {
            return Err("Field format error: missing closing parenthesis".to_string());
        }
        if flat.is_empty() {
            crate::panic_abort(LOC_EMPTY_LIST, MSG_EMPTY_LIST);
        }
        let formatted = flat.iter().any(|f| !f.prefix.is_empty()) || !lit.is_empty();
        Ok(BoundsList {
            flat,
            trailing: lit.into_bytes(),
            formatted,
        })
    }

    pub fn bounds_only(&self) -> Vec<UserBound> {
        self.flat.iter().map(|f| f.bound.clone()).collect()
    }

    /// Compute the complement of every bound in the list against a total
    /// of `n` items. Returns Err("the complement is empty") when nothing
    /// remains. Out-of-range endpoints abort with a panic, mirroring the
    /// original program.
    pub fn complemented(&self, n: usize) -> Result<BoundsList, String> {
        let mut new_flat: Vec<FlatBound> = Vec::new();
        for f in &self.flat {
            let segs = complement_segments(&f.bound, n);
            for (j, seg) in segs.into_iter().enumerate() {
                let prefix = if j == 0 {
                    f.prefix.clone()
                } else {
                    Vec::new()
                };
                new_flat.push(FlatBound {
                    bound: seg,
                    prefix,
                });
            }
        }
        if new_flat.is_empty() {
            return Err("the complement is empty".to_string());
        }
        Ok(BoundsList {
            flat: new_flat,
            trailing: self.trailing.clone(),
            formatted: self.formatted,
        })
    }

    /// Whether the bounds can be used by the line streaming reader:
    /// all sides positive and the expanded sequence non-decreasing.
    pub fn lines_is_forward(&self) -> bool {
        let mut prev_end: Option<i128> = None;
        for f in &self.flat {
            if f.bound.has_negative_side() {
                return false;
            }
            let (start, end) = f.bound.start_end_raw();
            if let Some(pe) = prev_end {
                if start < pe {
                    return false;
                }
            }
            prev_end = Some(end);
        }
        true
    }

    /// Whether the bounds can be converted to ForwardBounds for the
    /// fixed-memory reader.
    pub fn forward_conversion_ok(&self) -> bool {
        let mut prev: Option<(i128, i128, bool)> = None; // (start, end, is_point)
        for f in &self.flat {
            if f.bound.has_negative_side() {
                return false;
            }
            let (start, end) = f.bound.start_end_raw();
            let is_point = match &f.bound.kind {
                BoundKind::Single(_) => true,
                BoundKind::Range(_, Some(_)) => start == end,
                BoundKind::Range(_, None) => false,
            };
            if let Some((_, pend, ppoint)) = prev {
                if start < pend || (start == pend && ppoint) {
                    return false;
                }
            }
            prev = Some((start, end, is_point));
        }
        true
    }
}

fn range_bound(l: i128, r: Option<i128>) -> UserBound {
    let left = Some(Side::Start(l as i64));
    let right = r.map(|v| Side::Start(v as i64));
    UserBound {
        kind: BoundKind::Range(left, right),
        fallback: None,
    }
}

fn complement_segments(bound: &UserBound, n: usize) -> Vec<UserBound> {
    let ni = n as i128;
    let (l, r) = match &bound.kind {
        BoundKind::Single(side) => {
            let k = side.resolve(n);
            if k < 1 || k > ni {
                crate::panic_count_fields();
            }
            (k, k)
        }
        BoundKind::Range(left, right) => {
            let l = left.as_ref().map_or(1, |s| s.resolve(n));
