pub const MSG_EMPTY_LIST: &str = "UserBoundsList must contain at least one UserBounds";

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Side {
    // Positive, 1-based from the start. Always > 0.
    Start(i64),
    // Negative index, stored as its positive magnitude. Always > 0.
    End(i64),
}

impl Side {
    pub fn signed(&self) -> i64 {
        match *self {
            Side::Start(v) => v,
            Side::End(v) => -v,
        }
    }
    pub fn resolve(&self, n: usize) -> i128 {
        match *self {
            Side::Start(v) => v as i128,
            Side::End(v) => n as i128 - v as i128 + 1,
        }
    }
    pub fn display(&self) -> String {
        match *self {
            Side::Start(v) => v.to_string(),
            Side::End(v) => format!("-{v}"),
        }
    }
    pub fn is_end(&self) -> bool {
        matches!(self, Side::End(_))
    }
}

#[derive(Clone, Debug)]
pub enum BoundKind {
    Single(Side),
    // Left: None means 1. Right: None means open ended.
    Range(Option<Side>, Option<Side>),
}

#[derive(Clone, Debug)]
pub struct UserBound {
    pub kind: BoundKind,
    pub fallback: Option<String>,
}

impl UserBound {
    pub fn fallback_bytes(&self) -> Option<&[u8]> {
        self.fallback.as_ref().map(|s| s.as_bytes())
    }
    pub fn display(&self) -> String {
        match &self.kind {
            BoundKind::Single(s) => s.display(),
            BoundKind::Range(l, r) => format!(
                "{}:{}",
                l.as_ref().map_or_else(|| "1".to_string(), |s| s.display()),
                r.as_ref().map_or_else(String::new, |s| s.display())
            ),
        }
    }
    /// (start, end) as resolved symbolic values, with end = i128::MAX for
    /// an open range. Sides are returned as raw signed values.
    pub fn start_end_raw(&self) -> (i128, i128) {
        match &self.kind {
            BoundKind::Single(s) => {
                let v = s.signed() as i128;
                (v, v)
            }
            BoundKind::Range(l, r) => {
                let start = l.as_ref().map_or(1, |s| s.signed() as i128);
                let end = r.as_ref().map_or(i128::MAX, |s| s.signed() as i128);
                (start, end)
            }
        }
    }
    pub fn has_negative_side(&self) -> bool {
        match &self.kind {
            BoundKind::Single(s) => s.is_end(),
            BoundKind::Range(l, r) => {
                l.as_ref().map_or(false, |s| s.is_end()) || r.as_ref().map_or(false, |s| s.is_end())
            }
        }
    }
    pub fn is_point_range(&self) -> bool {
        match &self.kind {
            BoundKind::Range(Some(l), Some(r)) => l.signed() == r.signed(),
            _ => false,
        }
    }
}

#[derive(Clone, Debug)]
pub struct FlatBound {
    pub bound: UserBound,
    // Literal text that precedes this bound in a formatted bounds string.
    pub prefix: Vec<u8>,
}

#[derive(Clone, Debug)]
pub struct BoundsList {
    pub flat: Vec<FlatBound>,
    pub trailing: Vec<u8>,
    // True when the bounds string contained literal text outside of the
    // {..} placeholders (i.e. it is a real format string).
