                formatted: false,
            })
        }
    }

    fn parse_format(s: &str) -> Result<Self, String> {
        let chars: Vec<char> = s.chars().collect();
        let mut flat: Vec<FlatBound> = Vec::new();
        let mut lit = String::new();
        let mut content = String::new();
        let mut inside = false;
