                    } else {
                        return Err(
                            "Field format error: missing opening parenthesis".to_string()
                        );
                    }
                } else {
                    lit.push(c);
                    i += 1;
                }
            } else if c == '{' {
                if next == Some('{') {
                    content.push_str("{{");
                    i += 2;
                } else {
                    // A new opening brace while one is pending: the pending
                    // text becomes literal output and a new placeholder
                    // starts here.
                    lit.push_str(&unescape_braces(&content));
                    content.clear();
                    i += 1;
                }
            } else if c == '}' {
                if next == Some('}') {
                    content.push_str("}}");
                    i += 2;
                } else {
                    let bounds = parse_plain_list(&content, false)?;
                    for (j, b) in bounds.into_iter().enumerate() {
                        let prefix = if j == 0 {
                            std::mem::take(&mut lit).into_bytes()
                        } else {
                            Vec::new()
                        };
                        flat.push(FlatBound { bound: b, prefix });
                    }
                    inside = false;
                    content.clear();
                    i += 1;
                }
            } else {
                content.push(c);
                i += 1;
            }
        }
