    pub greedy: bool,
    pub compress: bool,
    pub only_delimited: bool,
    pub zero: bool,
    pub complement: bool,
    pub join: bool,
    pub nojoin: bool,
    pub json: bool,
    pub no_mmap: bool,
    pub replace: Option<String>,
    pub fixed_memory: Option<usize>,
    pub regex: Option<String>,
    pub trim: Option<Trim>,
    pub fallback: Option<String>,
    pub remaining: Vec<OsString>,
}

pub struct Parser {
    pub args: Vec<OsString>,
}

#[cfg(unix)]
fn os_bytes(s: &OsStr) -> &[u8] {
    s.as_bytes()
}
#[cfg(not(unix))]
fn os_bytes(s: &OsStr) -> &[u8] {
    // Command line parsing edge cases with non-UTF8 data are only
    // exercised on unix in practice.
    &[]
}

impl Parser {
    pub fn new(args: Vec<OsString>) -> Self {
        Parser { args }
    }

    fn exact_pos(&self, key: &str) -> Option<usize> {
        self.args.iter().position(|a| a.as_os_str() == OsStr::new(key))
    }

    /// Look for a boolean flag given as short and/or long keys.
    pub fn contains(&mut self, short: Option<char>, long: Option<&str>) -> bool {
        // Exact matches first, short key before long key.
        let mut keys: Vec<String> = Vec::new();
        if let Some(c) = short {
            keys.push(format!("-{c}"));
        }
        if let Some(l) = long {
            keys.push(l.to_string());
        }
        for key in &keys {
            if let Some(pos) = self.exact_pos(key) {
                self.args.remove(pos);
                return true;
            }
        }
        // Combined short flags, e.g. -gj: remove `c` from the cluster.
        if let Some(c) = short {
            let cb = c as u8;
            for i in 0..self.args.len() {
                let bytes = os_bytes(self.args[i].as_os_str()).to_vec();
                if bytes.len() >= 2 && bytes[0] == b'-' && bytes[1] != b'-' {
                    if let Some(rel) = bytes[1..].iter().position(|&b| b == cb) {
                        let mut rest: Vec<u8> = Vec::with_capacity(bytes.len() - 1);
                        rest.extend_from_slice(&bytes[1..1 + rel]);
                        rest.extend_from_slice(&bytes[1 + rel + 1..]);
                        if rest.is_empty() {
                            self.args.remove(i);
                        } else {
                            let mut newarg = vec![b'-'];
                            newarg.extend_from_slice(&rest);
                            #[cfg(unix)]
                            {
                                self.args[i] = OsString::from_vec(newarg);
                            }
                            #[cfg(not(unix))]
                            {
                                self.args[i] = OsString::from(String::from_utf8_lossy(&newarg).into_owned());
                            }
                        }
                        return true;
                    }
                }
            }
        }
        false
    }

    /// Look for an option with a value. Keys are searched exact-first,
    /// then in attached form (-f1, -f=1, --fields=1).
    pub fn opt_value(&mut self, short: &str, long: &str) -> Result<Option<String>, ArgError> {
        for key in [short, long] {
            if let Some(pos) = self.exact_pos(key) {
                self.args.remove(pos);
                if pos >= self.args.len() {
                    return Err(ArgError::missing(key));
                }
                let v = self.args.remove(pos);
                let v = v.into_string().map_err(|_| ArgError::not_utf8())?;
                return Ok(Some(v));
            }
        }
        for key in [short, long] {
            let is_long = key.starts_with("--");
            for i in 0..self.args.len() {
                let argstr = match self.args[i].to_str() {
                    Some(s) => s.to_string(),
                    None => continue,
                };
                if is_long {
                    let prefix = format!("{key}=");
                    if let Some(rest) = argstr.strip_prefix(&prefix) {
                        if rest.is_empty() {
                            return Err(ArgError::missing(key));
                        }
                        let value = rest.to_string();
                        self.args.remove(i);
                        return Ok(Some(value));
                    }
                } else if argstr.len() > key.len() && argstr.starts_with(key) {
                    let mut rest = &argstr[key.len()..];
                    if let Some(stripped) = rest.strip_prefix('=') {
                        rest = stripped;
                    }
                    if rest.is_empty() {
                        return Err(ArgError::missing(key));
                    }
                    let value = rest.to_string();
                    self.args.remove(i);
                    return Ok(Some(value));
                }
            }
        }
        Ok(None)
    }

    /// --fallback-oob is special: a trailing occurrence with no value
    /// is left in place (and later reported as an unexpected argument)
    /// instead of producing a missing-value error.
    pub fn opt_fallback(&mut self) -> Result<Option<String>, ArgError> {
        let key = "--fallback-oob";
        if let Some(pos) = self.exact_pos(key) {
            if pos + 1 < self.args.len() {
                self.args.remove(pos);
                let v = self.args.remove(pos);
                let v = v.into_string().map_err(|_| ArgError::not_utf8())?;
                return Ok(Some(v));
            }
            return Ok(None);
        }
        for i in 0..self.args.len() {
            let argstr = match self.args[i].to_str() {
                Some(s) => s.to_string(),
                None => continue,
            };
            if let Some(rest) = argstr.strip_prefix("--fallback-oob=") {
                let value = rest.to_string();
                self.args.remove(i);
                return Ok(Some(value));
            }
        }
        Ok(None)
    }
}

#[cfg(unix)]
trait OsVec {
    fn from_vec(v: Vec<u8>) -> OsString;
}
#[cfg(unix)]
impl OsVec for OsString {
    fn from_vec(v: Vec<u8>) -> OsString {
        use std::os::unix::ffi::OsStringExt;
        OsString::from_vec(v)
    }
}

fn parse_bounds(v: Option<String>) -> Result<Option<BoundsList>, ArgError> {
    match v {
        None => Ok(None),
        Some(s) => match BoundsList::parse(&s) {
            Ok(b) => Ok(Some(b)),
            Err(e) => Err(ArgError::failed(&s, e)),
        },
    }
}

pub fn parse_args(argv: Vec<OsString>) -> Result<RawOpts, ArgError> {
    let mut p = Parser::new(argv);
    let fields = parse_bounds(p.opt_value("-f", "--fields")?)?;
    let characters = parse_bounds(p.opt_value("-c", "--characters")?)?;
    let bytes = parse_bounds(p.opt_value("-b", "--bytes")?)?;
    let lines = parse_bounds(p.opt_value("-l", "--lines")?)?;
    let delimiter = p.opt_value("-d", "--delimiter")?;

    let greedy = p.contains(Some('g'), Some("--greedy-delimiter"));
    let compress = p.contains(Some('p'), Some("--compress-delimiter"));
    let only_delimited = p.contains(Some('s'), Some("--only-delimited"));
    let zero = p.contains(Some('z'), Some("--zero-terminated"));
    let complement = p.contains(Some('m'), Some("--complement"));
    let join = p.contains(Some('j'), Some("--join"));
    let nojoin = p.contains(None, Some("--no-join"));
    let json = p.contains(None, Some("--json"));
    let no_mmap = p.contains(None, Some("--no-mmap"));

    let replace = p.opt_value("-r", "--replace-delimiter")?;
    let fixed_memory = match p.opt_value("-M", "--fixed-memory")? {
        None => None,
        Some(s) => Some(
            s.parse::<usize>()
                .map_err(|e| ArgError::failed(&s, e.to_string()))?,
        ),
    };
    let regex = p.opt_value("-e", "--regex")?;
    let trim = match p.opt_value("-t", "--trim")? {
        None => None,
        Some(s) => Some(parse_trim(&s).map_err(|e| ArgError::failed(&s, e))?),
    };
    let fallback = p.opt_fallback()?;

    Ok(RawOpts {
        fields,
        characters,
        bytes,
        lines,
        delimiter,
        greedy,
        compress,
        only_delimited,
        zero,
        complement,
        join,
        nojoin,
        json,
        no_mmap,
        replace,
        fixed_memory,
        regex,
        trim,
        fallback,
        remaining: p.args,
    })
}

/// Detect a short flag character inside a combined cluster such as
/// `-xh`, or an exact long flag. Used for --help / --version lookups
/// which happen before any other parsing.
pub fn argv_contains_flag(argv: &[OsString], short: char, long: &str) -> bool {
    for a in argv {
        if a.as_os_str() == OsStr::new(long) {
            return true;
        }
        let bytes = os_bytes(a.as_os_str());
        if bytes.len() >= 2 && bytes[0] == b'-' && bytes[1] != b'-' {
            if bytes[1..].contains(&(short as u8)) {
                return true;
            }
        }
    }
    false
}
