cat > src/cut.rs <<'RS'
// The cutting engine: fields, characters, bytes and lines modes.

use crate::args::Trim;
use crate::bounds::{BoundKind, BoundsList, Side, UserBound};
use regex::bytes::Regex;
use std::borrow::Cow;
use std::io::Write;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Mode {
    Fields,
    Chars,
    Bytes,
    Lines,
}

pub struct Config {
    pub mode: Mode,
    pub bounds: BoundsList,
    pub delimiter: Vec<u8>,
    pub regex: Option<Regex>,
    pub replace: Option<Vec<u8>>,
    pub trim: Option<Trim>,
    pub greedy: bool,
    pub compress: bool,
    pub only_delimited: bool,
    pub zero: bool,
    pub complement: bool,
    pub join: bool,
    pub nojoin: bool,
    pub json: bool,
    pub fixed_memory: Option<usize>,
    pub generic_fallback: Option<Vec<u8>>,
}

impl Config {
    pub fn eol(&self) -> u8 {
        if self.zero {
            0
        } else {
            b'\n'
        }
    }
    pub fn join_enabled(&self) -> bool {
        self.join || self.replace.is_some()
    }
    pub fn fields_join_delim(&self) -> Vec<u8> {
        match &self.replace {
            Some(r) => r.clone(),
            None => self.delimiter.clone(),
        }
    }
}

#[derive(Debug)]
pub enum ProcError {
    Msg(String),
}

pub type PResult<T> = Result<T, ProcError>;

fn err_msg<T>(s: String) -> PResult<T> {
    Err(ProcError::Msg(s))
}

fn w(out: &mut dyn Write, bytes: &[u8]) -> PResult<()> {
    out.write_all(bytes)
        .map_err(|e| ProcError::Msg(e.to_string()))
}

fn w_eol(cfg: &Config, out: &mut dyn Write) -> PResult<()> {
    w(out, &[cfg.eol()])
}

pub fn split_lines(data: &[u8], eol: u8) -> Vec<&[u8]> {
    if data.is_empty() {
        return Vec::new();
    }
    let mut v: Vec<&[u8]> = data.split(|b| *b == eol).collect();
    if data.last() == Some(&eol) {
        v.pop();
    }
    v
}

// ---------- delimiter matching ----------

fn regex_matches(re: &Regex, line: &[u8]) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let mut pos = 0usize;
    while pos <= line.len() {
        let m = match re.find_at(line, pos) {
            Some(m) => m,
            None => break,
        };
        out.push((m.start(), m.end()));
        if m.start() == m.end() {
            if m.end() >= line.len() {
                break;
            }
            pos = m.end() + 1;
        } else {
            pos = m.end();
        }
    }
    out
}

fn delimiter_matches(cfg: &Config, line: &[u8]) -> Vec<(usize, usize)> {
    if let Some(re) = &cfg.regex {
        return regex_matches(re, line);
    }
    if cfg.delimiter.is_empty() {
        return (0..=line.len()).map(|i| (i, i)).collect();
    }
    memchr::memmem::find_iter(line, &cfg.delimiter)
        .map(|p| (p, p + cfg.delimiter.len()))
        .collect()
}

fn group_matches(matches: Vec<(usize, usize)>) -> Vec<(usize, usize)> {
    let mut groups: Vec<(usize, usize)> = Vec::new();
    for m in matches {
        if let Some(last) = groups.last_mut() {
            if m.0 == last.1 {
                last.1 = m.1;
                continue;
            }
        }
        groups.push(m);
    }
    groups
}

// ---------- preprocessing (fields mode) ----------

fn trim_line<'a>(cfg: &Config, line: &'a [u8]) -> &'a [u8] {
    let trim = match cfg.trim {
        Some(t) => t,
        None => return line,
    };
    let mut l = line;
    if trim == Trim::Left || trim == Trim::Both {
        if let Some(re) = &cfg.regex {
            loop {
                match re.find_at(l, 0) {
                    Some(m) if m.start() == 0 && m.end() > 0 => {
                        l = &l[m.end()..];
                    }
                    _ => break,
                }
            }
        } else {
            while l.starts_with(&cfg.delimiter) {
                l = &l[cfg.delimiter.len()..];
            }
        }
    }
    if trim == Trim::Right || trim == Trim::Both {
        if let Some(re) = &cfg.regex {
            loop {
                let cand = regex_matches(re, l)
                    .into_iter()
                    .filter(|m| m.1 == l.len() && m.1 > m.0)
                    .last();
                match cand {
                    Some(m) => {
                        l = &l[..m.0];
                    }
                    None => break,
                }
            }
        } else {
            while l.ends_with(&cfg.delimiter) {
                l = &l[..l.len() - cfg.delimiter.len()];
            }
        }
    }
    l
}

fn compress_line(cfg: &Config, line: &[u8]) -> Vec<u8> {
    let matches = delimiter_matches(cfg, line);
    if matches.is_empty() {
        return line.to_vec();
    }
    let mut out = Vec::with_capacity(line.len());
    let mut prev_end = 0usize;
    let mut prev_match: Option<(usize, usize)> = None;
    for (s, e) in matches {
        out.extend_from_slice(&line[prev_end..s]);
        let continuation = prev_match.map_or(false, |pm| pm.1 == s);
        if !continuation {
            out.extend_from_slice(&line[s..e]);
        }
        prev_end = e;
        prev_match = Some((s, e));
    }
    out.extend_from_slice(&line[prev_end..]);
    out
}

fn preprocess<'a>(cfg: &Config, line: &'a [u8]) -> Cow<'a, [u8]> {
    let trimmed = trim_line(cfg, line);
    if cfg.compress {
        Cow::Owned(compress_line(cfg, trimmed))
    } else {
        Cow::Borrowed(trimmed)
    }
}

fn contains_delimiter(cfg: &Config, line: &[u8]) -> bool {
    if let Some(re) = &cfg.regex {
        re.is_match(line)
    } else if cfg.delimiter.is_empty() {
        true
    } else {
        memchr::memmem::find(line, &cfg.delimiter).is_some()
    }
}

// ---------- field spans ----------

#[derive(Clone)]
struct FieldsInfo<'a> {
    line: &'a [u8],
    starts: Vec<usize>,
    ends: Vec<usize>,
}

impl<'a> FieldsInfo<'a> {
    fn len(&self) -> usize {
        self.starts.len()
    }
    fn text(&self, idx1: usize) -> &'a [u8] {
        &self.line[self.starts[idx1 - 1]..self.ends[idx1 - 1]]
    }
    fn span(&self, l: usize, r: usize) -> &'a [u8] {
        &self.line[self.starts[l - 1]..self.ends[r - 1]]
    }
    fn single(line: &'a [u8]) -> Self {
        FieldsInfo {
            line,
            starts: vec![0],
            ends: vec![line.len()],
        }
    }
}

fn fields_info<'a>(cfg: &Config, line: &'a [u8]) -> FieldsInfo<'a> {
    let matches = delimiter_matches(cfg, line);
    let matches = if cfg.greedy {
        group_matches(matches)
    } else {
        matches
    };
    let mut starts = Vec::new();
    let mut ends = Vec::new();
    let mut prev = 0usize;
    for (s, e) in &matches {
        starts.push(prev);
        ends.push(*s);
        prev = *e;
    }
    starts.push(prev);
    ends.push(line.len());
    FieldsInfo {
        line,
        starts,
        ends,
    }
}

// ---------- replacements ----------

fn replace_bytes(hay: &[u8], needle: &[u8], rep: &[u8]) -> Vec<u8> {
    if needle.is_empty() {
        let mut out = Vec::new();
        for &b in hay {
            out.extend_from_slice(rep);
            out.push(b);
        }
        out.extend_from_slice(rep);
        return out;
    }
    let mut out = Vec::new();
    let mut pos = 0usize;
    for p in memchr::memmem::find_iter(hay, needle) {
        out.extend_from_slice(&hay[pos..p]);
        out.extend_from_slice(rep);
        pos = p + needle.len();
    }
    out.extend_from_slice(&hay[pos..]);
    out
}

fn transform_replace(cfg: &Config, slice: &[u8]) -> Vec<u8> {
    match &cfg.replace {
        None => slice.to_vec(),
        Some(rep) => {
            if let Some(re) = &cfg.regex {
                re.replace_all(slice, &rep[..]).into_owned()
            } else {
                replace_bytes(slice, &cfg.delimiter, rep)
            }
        }
    }
}

fn fallback_for<'a>(cfg: &'a Config, bound: &'a UserBound) -> Option<&'a [u8]> {
    bound
        .fallback_bytes()
        .or(cfg.generic_fallback.as_deref())
}

fn oob_or_fallback(cfg: &Config, bound: &UserBound, err: String) -> PResult<Vec<u8>> {
    if let Some(fb) = fallback_for(cfg, bound) {
        Ok(fb.to_vec())
    } else {
        err_msg(err)
    }
}

fn oob_err(side: &Side) -> String {
    format!("Out of bounds: {}", side.display())
}

// ---------- segments for fields ----------

fn field_segment(cfg: &Config, info: &FieldsInfo, bound: &UserBound) -> PResult<Vec<u8>> {
    let n = info.len();
    match &bound.kind {
        BoundKind::Single(side) => {
            let idx = side.resolve(n);
            if idx < 1 || idx > n as i128 {
                return oob_or_fallback(cfg, bound, oob_err(side));
            }
            Ok(transform_replace(cfg, info.text(idx as usize)))
        }
        BoundKind::Range(left, right) => {
            let l = left.as_ref().map_or(1, |s| s.resolve(n));
            if l < 1 || l > n as i128 {
                let disp = left
                    .as_ref()
                    .map_or_else(|| "1".to_string(), |s| s.display());
                return oob_or_fallback(cfg, bound, format!("Out of bounds: {disp}"));
            }
            let r: i128 = match right {
                None => n as i128,
                Some(s) => {
                    let rr = s.resolve(n);
                    if rr < 1 {
                        1
                    } else if rr > n as i128 {
                        n as i128
                    } else {
                        rr
                    }
                }
            };
            if l > r {
                return oob_or_fallback(
                    cfg,
                    bound,
                    "Field left value cannot be greater than right value".to_string(),
                );
            }
            Ok(transform_replace(
                cfg,
                info.span(l as usize, r as usize),
            ))
        }
    }
}

// ---------- generic (chars / JSON) range handling ----------

enum GenericExpand {
    Single(Side),
    Range(usize, usize),
}

fn generic_expand(bound: &UserBound, n: usize) -> GenericExpand {
    match &bound.kind {
        BoundKind::Single(side) => GenericExpand::Single(side.clone()),
        BoundKind::Range(left, right) => {
            if bound.is_point_range() {
                return GenericExpand::Single(left.as_ref().unwrap().clone());
            }
            let ni = n as i128;
            let l = left.as_ref().map_or(1, |s| s.resolve(n));
            if right.is_none() {
                if l < 1 || l > ni {
                    crate::panic_count224();
                }
                return GenericExpand::Range(l as usize, n);
            }
            let r = right.as_ref().unwrap().resolve(n);
            if l < 1 || l > ni || r < 1 || r > ni {
                crate::panic_count224();
            }
            if l > r {
                crate::panic_empty_list();
            }
            GenericExpand::Range(l as usize, r as usize)
        }
    }
}

fn single_element(
    cfg: &Config,
    items: &[&[u8]],
    side: &Side,
    bound: &UserBound,
) -> PResult<Vec<u8>> {
    let idx = side.resolve(items.len());
    if idx < 1 || idx > items.len() as i128 {
        return oob_or_fallback(cfg, bound, oob_err(side));
    }
    Ok(items[(idx - 1) as usize].to_vec())
}

// ---------- flat rendering ----------

fn render_flat(
    out: &mut dyn Write,
    cfg: &Config,
    bounds: &BoundsList,
    join_enabled: bool,
    join_delim: &[u8],
    end_eol: bool,
    resolver: &mut dyn FnMut(&UserBound) -> PResult<Vec<u8>>,
) -> PResult<()> {
    for (i, flat) in bounds.flat.iter().enumerate() {
        if i > 0 && join_enabled {
            w(out, join_delim)?;
        }
        w(out, &flat.prefix)?;
        let seg = resolver(&flat.bound)?;
        w(out, &seg)?;
    }
    w(out, &bounds.trailing)?;
    if end_eol {
        w_eol(cfg, out)?;
    }
    Ok(())
}

// ---------- JSON ----------

fn write_json_string(out: &mut dyn Write, bytes: &[u8]) -> PResult<()> {
    w(out, b"\"")?;
    for &b in bytes {
        match b {
            b'"' => w(out, b"\\\"")?,
            b'\\' => w(out, b"\\\\")?,
            0x08 => w(out, b"\\b")?,
            0x0c => w(out, b"\\f")?,
            b'\n' => w(out, b"\\n")?,
            b'\r' => w(out, b"\\r")?,
            b'\t' => w(out, b"\\t")?,
            0x00..=0x1f => {
                w(out, format!("\\u{b:04x}").as_bytes())?;
            }
            _ => w(out, &[b])?,
        }
    }
    w(out, b"\"")
}

fn render_json(
    out: &mut dyn Write,
    cfg: &Config,
    items: &[&[u8]],
) -> PResult<()> {
    w(out, b"[")?;
    let comp;
    let bounds: &BoundsList = if cfg.complement {
        comp = cfg
            .bounds
            .complemented(items.len())
            .map_err(ProcError::Msg)?;
        &comp
    } else {
        &cfg.bounds
    };
    let mut first = true;
    for flat in &bounds.flat {
        match generic_expand(&flat.bound, items.len()) {
            GenericExpand::Single(side) => {
                if !first {
                    w(out, b",")?;
                }
                let el = single_element(cfg, items, &side, &flat.bound)?;
                write_json_string(out, &el)?;
                first = false;
            }
            GenericExpand::Range(l, r) => {
                for idx in l..=r {
                    if !first {
                        w(out, b",")?;
                    }
                    write_json_string(out, items[idx - 1])?;
                    first = false;
                }
            }
        }
    }
    w(out, b"]")?;
    w_eol(cfg, out)
}

// ---------- characters ----------

fn char_slices(line: &[u8]) -> Vec<&[u8]> {
    let mut out = Vec::new();
    let mut i = 0usize;
    while i < line.len() {
        let b = line[i];
        let width = if b < 0x80 {
            1
        } else if b & 0xE0 == 0xC0 {
            2
        } else if b & 0xF0 == 0xE0 {
            3
        } else if b & 0xF8 == 0xF0 {
            4
        } else {
            1
        };
        let end = std::cmp::min(i + width, line.len());
        out.push(&line[i..end]);
        i = end;
    }
    out
}

fn process_chars(cfg: &Config, data: &[u8], out: &mut dyn Write) -> PResult<()> {
    for line in split_lines(data, cfg.eol()) {
        if line.is_empty() {
            w_eol(cfg, out)?;
            continue;
        }
        let items = char_slices(line);
        if cfg.json {
            render_json(out, cfg, &items)?;
            continue;
        }
        let comp;
        let bounds: &BoundsList = if cfg.complement {
            comp = cfg
                .bounds
                .complemented(items.len())
                .map_err(ProcError::Msg)?;
            &comp
        } else {
            &cfg.bounds
        };
        let join_delim = cfg.replace.clone().unwrap_or_default();
        let items_ref = &items;
        render_flat(
            out,
            cfg,
            bounds,
            cfg.join_enabled(),
            &join_delim,
            true,
            &mut |bound: &UserBound| -> PResult<Vec<u8>> {
                match generic_expand(bound, items_ref.len()) {
                    GenericExpand::Single(side) => {
                        single_element(cfg, items_ref, &side, bound)
                    }
                    GenericExpand::Range(l, r) => {
                        let sep = cfg.replace.clone().unwrap_or_default();
                        let mut seg = Vec::new();
                        for (k, idx) in (l..=r).enumerate() {
                            if k > 0 {
                                seg.extend_from_slice(&sep);
                            }
                            seg.extend_from_slice(items_ref[idx - 1]);
                        }
                        Ok(seg)
                    }
                }
            },
        )?;
    }
    Ok(())
}

// ---------- bytes ----------

fn process_bytes(cfg: &Config, data: &[u8], out: &mut dyn Write) -> PResult<()> {
    if data.is_empty() {
        return Ok(());
    }
    let n = data.len();
    render_flat(
        out,
        cfg,
        &cfg.bounds,
        false,
        &[],
        false,
        &mut |bound: &UserBound| -> PResult<Vec<u8>> {
            match &bound.kind {
                BoundKind::Single(side) => {
                    let idx = side.resolve(n);
                    if idx < 1 || idx > n as i128 {
                        return err_msg(oob_err(side));
                    }
                    Ok(vec![data[(idx - 1) as usize]])
                }
                BoundKind::Range(left, right) => {
                    let l = left.as_ref().map_or(1, |s| s.resolve(n));
                    if l < 1 || l > n as i128 {
                        let disp = left
                            .as_ref()
                            .map_or_else(|| "1".to_string(), |s| s.display());
                        return err_msg(format!("Out of bounds: {disp}"));
                    }
                    let r: i128 = match right {
                        None => n as i128,
                        Some(s) => {
                            let rr = s.resolve(n);
                            if rr < 1 {
                                1
                            } else if rr > n as i128 {
                                n as i128
                            } else {
                                rr
                            }
                        }
                    };
                    if l > r {
                        return err_msg(
                            "Field left value cannot be greater than right value".to_string(),
                        );
                    }
                    Ok(data[(l - 1) as usize..r as usize].to_vec())
                }
            }
        },
    )
}

// ---------- fields ----------

fn process_fields(cfg: &Config, data: &[u8], out: &mut dyn Write) -> PResult<()> {
    for line in split_lines(data, cfg.eol()) {
        let processed = preprocess(cfg, line);
        if cfg.only_delimited && !contains_delimiter(cfg, &processed) {
            continue;
        }
        if processed.is_empty() {
            w_eol(cfg, out)?;
            continue;
        }
        let info = fields_info(cfg, &processed);
        if cfg.json {
            let items: Vec<&[u8]> = (0..info.len()).map(|i| info.text(i + 1)).collect();
            render_json(out, cfg, &items)?;
            continue;
        }
        let comp;
        let bounds: &BoundsList = if cfg.complement {
            comp = cfg
                .bounds
                .complemented(info.len())
                .map_err(ProcError::Msg)?;
            &comp
        } else {
            &cfg.bounds
        };
        let join_delim = cfg.fields_join_delim();
        render_flat(
            out,
            cfg,
            bounds,
            cfg.join_enabled(),
            &join_delim,
            true,
            &mut |bound: &UserBound| field_segment(cfg, &info, bound),
        )?;
    }
    Ok(())
}

// ---------- fields with fixed memory ----------

struct FixedState<'a> {
    cfg: &'a Config,
    info: FieldsInfo<'a>,
    cursor: i128,
    last: Option<usize>,
}

impl<'a> FixedState<'a> {
    fn write_field(&mut self, out: &mut dyn Write, idx: usize) -> PResult<()> {
        if let Some(prev) = self.last {
            if idx == prev + 1 {
                if let Some(rep) = &self.cfg.replace {
                    w(out, rep)?;
                } else {
                    let s = self.info.ends[prev - 1];
                    let e = self.info.starts[idx - 1];
                    w(out, &self.info.line[s..e])?;
                }
            } else if idx > prev + 1 && self.cfg.join_enabled() {
                w(out, &self.cfg.fields_join_delim())?;
            }
        } else if self.cfg.join_enabled() && idx > 1 {
            w(out, &self.cfg.fields_join_delim())?;
        }
        w(out, self.info.text(idx))?;
        self.last = Some(idx);
        Ok(())
    }

    fn write_fallback(&mut self, out: &mut dyn Write, bound: &UserBound) -> PResult<bool> {
        if let Some(fb) = fallback_for(self.cfg, bound) {
            let fb = fb.to_vec();
            w(out, &fb)?;
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn process_bound(&mut self, out: &mut dyn Write, bound: &UserBound) -> PResult<()> {
        let n = self.info.len() as i128;
        match &bound.kind {
            BoundKind::Single(side) => {
                let idx = side.resolve(self.info.len());
                if idx < self.cursor || idx > n {
                    if !self.write_fallback(out, bound)? {
                        return err_msg(oob_err(side));
                    }
                } else {
                    self.write_field(out, idx as usize)?;
                    self.cursor = idx + 1;
                }
                Ok(())
            }
            BoundKind::Range(left, right) => {
                let l = left.as_ref().map_or(1, |s| s.resolve(self.info.len()));
                match right {
                    None => {
                        let start = std::cmp::max(l, self.cursor);
                        if start <= n {
                            let mut idx = start;
                            while idx <= n {
                                self.write_field(out, idx as usize)?;
                                idx += 1;
                            }
                            self.cursor = n + 1;
                        }
                        Ok(())
                    }
                    Some(rside) => {
                        let r = rside.resolve(self.info.len());
                        if l > n {
                            if !self.write_fallback(out, bound)? {
                                let disp = left
                                    .as_ref()
                                    .map_or_else(|| "1".to_string(), |s| s.display());
                                return err_msg(format!("Out of bounds: {disp}"));
                            }
                            return Ok(());
                        }
                        let start = std::cmp::max(l, self.cursor);
                        let end = std::cmp::min(r, n);
                        if start > end {
                            if !self.write_fallback(out, bound)? {
                                let disp = left
                                    .as_ref()
                                    .map_or_else(|| "1".to_string(), |s| s.display());
                                return err_msg(format!("Out of bounds: {disp}"));
                            }
                            return Ok(());
                        }
                        let mut idx = start;
                        while idx <= end {
                            self.write_field(out, idx as usize)?;
                            idx += 1;
                        }
                        self.cursor = std::cmp::max(self.cursor, end + 1);
                        if r > n {
                            if !self.write_fallback(out, bound)? {
                                let disp = left
                                    .as_ref()
                                    .map_or_else(|| "1".to_string(), |s| s.display());
                                return err_msg(format!("Out of bounds: {disp}"));
                            }
                        }
                        Ok(())
                    }
                }
            }
        }
    }
}

fn process_fields_fixed(cfg: &Config, data: &[u8], out: &mut dyn Write) -> PResult<()> {
    for line in split_lines(data, cfg.eol()) {
        let info = if line.is_empty() {
            FieldsInfo {
                line,
                starts: Vec::new(),
                ends: Vec::new(),
            }
        } else {
            fields_info(cfg, line)
        };
        if cfg.bounds.formatted {
            // Formatted bounds are rendered with the ordinary field
            // renderer; the fixed-memory reader only changes how the
            // input is consumed.
            let join_delim = cfg.fields_join_delim();
            render_flat(
                out,
                cfg,
                &cfg.bounds,
                cfg.join_enabled(),
                &join_delim,
                true,
                &mut |bound: &UserBound| field_segment(cfg, &info, bound),
            )?;
            continue;
        }
        let mut state = FixedState {
            cfg,
            info,
            cursor: 1,
            last: None,
        };
        for flat in &cfg.bounds.flat {
            state.process_bound(out, &flat.bound)?;
        }
        w_eol(cfg, out)?;
    }
    Ok(())
}

// ---------- lines ----------

fn strict_line_segment(line: &[u8], bound: &UserBound) -> PResult<Vec<u8>> {
    match &bound.kind {
        BoundKind::Single(side) => {
            if side.resolve(1) != 1 {
                return err_msg(oob_err(side));
            }
            Ok(line.to_vec())
        }
        BoundKind::Range(left, right) => {
            let l = left.as_ref().map_or(1, |s| s.resolve(1));
            let r = right.as_ref().map_or(1, |s| s.resolve(1));
            if l != 1 {
                let disp = left
                    .as_ref()
                    .map_or_else(|| "1".to_string(), |s| s.display());
                return err_msg(format!("Out of bounds: {disp}"));
            }
            if r == 1 {
                return Ok(line.to_vec());
            }
            if r < 1 {
                let disp = right
                    .as_ref()
                    .map_or_else(String::new, |s| s.display());
                return err_msg(format!("Out of bounds: {disp}"));
            }
            // r > 1
            let disp = if let Some(ls) = left {
                if ls.is_end() {
                    ls.display()
                } else {
                    right
                        .as_ref()
                        .map_or_else(String::new, |s| s.display())
                }
            } else {
                right
                    .as_ref()
                    .map_or_else(String::new, |s| s.display())
            };
            err_msg(format!("Out of bounds: {disp}"))
        }
    }
}

fn process_lines_fallback(cfg: &Config, data: &[u8], out: &mut dyn Write) -> PResult<()> {
    let eolb = [cfg.eol()];
    for line in split_lines(data, cfg.eol()) {
        render_flat(
            out,
            cfg,
            &cfg.bounds,
            !cfg.nojoin,
            &eolb,
            true,
            &mut |bound: &UserBound| strict_line_segment(line, bound),
        )?;
    }
    Ok(())
}

fn process_lines_complement(cfg: &Config, data: &[u8], out: &mut dyn Write) -> PResult<()> {
    let eolb = [cfg.eol()];
    for line in split_lines(data, cfg.eol()) {
        if line.is_empty() {
            w_eol(cfg, out)?;
            continue;
        }
        let info = FieldsInfo::single(line);
        let comp = cfg
            .bounds
            .complemented(1)
            .map_err(ProcError::Msg)?;
        render_flat(
            out,
            cfg,
            &comp,
            !cfg.nojoin,
            &eolb,
            true,
            &mut |bound: &UserBound| field_segment(cfg, &info, bound),
        )?;
    }
    Ok(())
}

enum Block {
    Text(Vec<u8>),
    Bound(UserBound),
}

fn process_lines_stream(cfg: &Config, data: &[u8], out: &mut dyn Write) -> PResult<()> {
    let lines = split_lines(data, cfg.eol());
    let n = lines.len() as i128;
    let mut blocks: Vec<Block> = Vec::new();
    for flat in &cfg.bounds.flat {
        if !flat.prefix.is_empty() {
            blocks.push(Block::Text(flat.prefix.clone()));
        }
        blocks.push(Block::Bound(flat.bound.clone()));
    }
    if !cfg.bounds.trailing.is_empty() {
        blocks.push(Block::Text(cfg.bounds.trailing.clone()));
    }
    for (i, block) in blocks.iter().enumerate() {
        if i > 0 && !cfg.nojoin {
            w_eol(cfg, out)?;
        }
        match block {
            Block::Text(t) => {
                w(out, t)?;
            }
            Block::Bound(bound) => match &bound.kind {
                BoundKind::Single(side) => {
                    let idx = side.signed() as i128;
                    if idx < 1 || idx > n {
                        return err_msg(oob_err(side));
                    }
                    w(out, lines[(idx - 1) as usize])?;
                }
                BoundKind::Range(left, right) => {
                    let l = left.as_ref().map_or(1, |s| s.signed() as i128);
                    match right {
                        None => {
                            if l <= n {
                                let mut idx = l;
                                while idx <= n {
                                    if idx > l {
                                        w_eol(cfg, out)?;
                                    }
                                    w(out, lines[(idx - 1) as usize])?;
                                    idx += 1;
                                }
                            }
                        }
                        Some(rside) => {
                            let r = rside.signed() as i128;
                            if l > n {
                                return err_msg(format!(
                                    "Out of bounds: {}",
                                    bound.display()
                                ));
                            }
                            let end = std::cmp::min(r, n);
                            let mut idx = l;
                            while idx <= end {
                                if idx > l {
                                    w_eol(cfg, out)?;
                                }
                                w(out, lines[(idx - 1) as usize])?;
                                idx += 1;
                            }
                            if r > n {
                                return err_msg(format!(
                                    "Out of bounds: {}",
                                    bound.display()
                                ));
                            }
                        }
                    }
                }
            },
        }
    }
    w_eol(cfg, out)
}

fn process_lines(cfg: &Config, data: &[u8], out: &mut dyn Write) -> PResult<()> {
    if cfg.complement {
        process_lines_complement(cfg, data, out)
    } else if cfg.compress || !cfg.bounds.lines_is_forward() {
        process_lines_fallback(cfg, data, out)
    } else {
        process_lines_stream(cfg, data, out)
    }
}

// ---------- entry ----------

pub fn process(cfg: &Config, data: &[u8], out: &mut dyn Write) -> PResult<()> {
    match cfg.mode {
        Mode::Fields => {
            if cfg.fixed_memory.is_some() {
                process_fields_fixed(cfg, data, out)
            } else {
                process_fields(cfg, data, out)
            }
        }
        Mode::Chars => process_chars(cfg, data, out),
        Mode::Bytes => process_bytes(cfg, data, out),
        Mode::Lines => process_lines(cfg, data, out),
    }
}
