        "/workspace/src/cut_str.rs:197:46",
        "We didn't use an extract function that counted the number of fields",
    )
}

pub fn panic_count224() -> ! {
    panic_abort(
        "/workspace/src/cut_str.rs:224:22",
        "We didn't use an extract function that counted the number of fields",
    )
}

pub fn panic_empty_list() -> ! {
    panic_abort(bounds::LOC_EMPTY_LIST, bounds::MSG_EMPTY_LIST)
}

fn use_color() -> bool {
    if env::var_os("NO_COLOR").is_some() {
        return false;
    }
    match env::var("TERM") {
        Ok(t) if !t.is_empty() && t != "dumb" => io::stdout().is_terminal(),
        _ => false,
    }
}

fn print_bytes(bytes: &[u8]) {
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(bytes);
    let _ = lock.flush();
}

fn runtime_error(msg: &str) -> ! {
    eprintln!("tuc: runtime error. {msg}");
    exit(1);
}

fn build_config(raw: &RawOpts) -> Result<Config, String> {
    let (mode, bounds) = if let Some(b) = &raw.fields {
        (Mode::Fields, b.clone())
    } else if let Some(b) = &raw.characters {
        (Mode::Chars, b.clone())
    } else if let Some(b) = &raw.bytes {
        (Mode::Bytes, b.clone())
    } else if let Some(b) = &raw.lines {
        (Mode::Lines, b.clone())
    } else {
        (Mode::Fields, BoundsList::parse("1:").unwrap())
    };
    let delimiter_str = raw.delimiter.clone().unwrap_or_else(|| "\t".to_string());

    if raw.fixed_memory == Some(0) {
        return Err("--fixed-memory cannot be 0".to_string());
    }
    if raw.join && raw.nojoin {
        return Err("It's not possible to use --join and --no-join simultaneously".to_string());
    }
    if raw.json && raw.nojoin {
        return Err("Using both --json and --no-join is not permitted".to_string());
    }
    if raw.nojoin && raw.replace.is_some() {
        return Err(
            "You can't pass --no-join when using --replace, which implies --join".to_string(),
        );
    }
    if raw.json && raw.replace.is_some() {
        return Err("The use of --replace with --json is not supported".to_string());
    }
    if raw.json && mode != Mode::Fields && mode != Mode::Chars {
        return Err("--json support is available only for --fields and --characters".to_string());
    }
    if raw.json && bounds.formatted {
        return Err("Cannot format fields when using --json".to_string());
    }

    let mut compiled_regex = None;
    if let Some(pattern) = &raw.regex {
        if mode != Mode::Chars {
            let re = regex::bytes::Regex::new(pattern).map_err(|e| {
                format!("The regular expression is malformed. {e}")
            })?;
            let join_for_check = match mode {
                Mode::Fields | Mode::Bytes => raw.join,
                Mode::Lines => !raw.nojoin,
                Mode::Chars => false,
            };
            if join_for_check && raw.replace.is_none() {
                return Err(
                    "Cannot use --regex and --join without --replace-delimiter".to_string(),
                );
            }
            if raw.compress && raw.replace.is_none() {
                return Err(
                    "Cannot use --regex and --compress-delimiter without --replace-delimiter"
                        .to_string(),
                );
            }
            compiled_regex = Some(re);
        }
    }
    if raw.compress && mode != Mode::Fields && mode != Mode::Lines {
        return Err("Delimiters can be compressed only with --fields and --lines".to_string());
    }

    if raw.fixed_memory.is_some() {
        match mode {
            Mode::Bytes | Mode::Chars => {
                return Err("Delimiter must be 1 byte wide for FastOpt".to_string());
            }
            Mode::Lines => {
                return Err(
                    "StreamOpt supports solely forward fields, join and single-character delimiters"
                        .to_string(),
                );
            }
            Mode::Fields => {
                if delimiter_str.len() != 1 {
                    return Err("Delimiter must be 1 byte wide for FastOpt".to_string());
                }
                if raw.greedy
                    || raw.compress
                    || raw.only_delimited
                    || raw.complement
                    || raw.json
                    || raw.trim.is_some()
                    || raw.regex.is_some()
                {
                    return Err(
                        "StreamOpt supports solely forward fields, join and single-character delimiters"
                            .to_string(),
                    );
                }
                if !bounds.forward_conversion_ok() {
                    return Err("Bounds cannot be converted to ForwardBounds".to_string());
                }
            }
        }
    }

    Ok(Config {
        mode,
        bounds,
        delimiter: delimiter_str.into_bytes(),
        regex: compiled_regex,
        replace: raw.replace.as_ref().map(|s| s.clone().into_bytes()),
        trim: raw.trim,
        greedy: raw.greedy,
        compress: raw.compress,
        only_delimited: raw.only_delimited,
        zero: raw.zero,
        complement: raw.complement,
        join: raw.join,
        nojoin: raw.nojoin,
        json: raw.json,
        fixed_memory: raw.fixed_memory,
        generic_fallback: raw.fallback.as_ref().map(|s| s.clone().into_bytes()),
    })
}

fn read_input(path: &Option<String>, no_mmap: bool) -> Result<Vec<u8>, String> {
    match path {
        None => {
            let mut v = Vec::new();
            io::stdin()
                .lock()
                .read_to_end(&mut v)
                .map_err(|e| e.to_string())?;
            Ok(v)
        }
        Some(p) => {
            use std::os::unix::io::AsRawFd;
            let mut file = std::fs::File::open(p)
                .map_err(|e| format!("{e}.\nWas attempting to read {p:?}"))?;
            if no_mmap {
                let mut v = Vec::new();
                file.read_to_end(&mut v).map_err(|e| e.to_string())?;
                return Ok(v);
            }
            let len = file
                .metadata()
                .map_err(|e| e.to_string())?
                .len();
            if len == 0 {
                return Ok(Vec::new());
            }
            unsafe {
                let ptr = libc::mmap(
                    std::ptr::null_mut(),
                    len as usize,
                    libc::PROT_READ,
                    libc::MAP_PRIVATE,
                    file.as_raw_fd(),
                    0,
                );
                if ptr == libc::MAP_FAILED {
                    return Err(io::Error::last_os_error().to_string());
                }
                let v = std::slice::from_raw_parts(ptr as *const u8, len as usize).to_vec();
                libc::munmap(ptr, len as usize);
                Ok(v)
            }
        }
    }
}

fn main() {
    let argv: Vec<OsString> = env::args_os().skip(1).collect();

    if argv.is_empty() {
        if use_color() {
            print_bytes(ABOUT_COLOR);
        } else {
            print_bytes(ABOUT_PLAIN);
        }
        return;
    }
    if argv_contains_flag(&argv, 'h', "--help") {
        if use_color() {
            print_bytes(HELP_COLOR);
        } else {
            print_bytes(HELP_PLAIN);
        }
        return;
    }
    if argv_contains_flag(&argv, 'V', "--version") {
        print_bytes(b"tuc 1.3.0\n");
        return;
    }

    let raw = match parse_args(argv) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("{}", e.0);
            exit(1);
        }
    };

    // Determine the input path from whatever arguments are left.
    let path: Option<String> = if raw.remaining.len() > 1 {
        eprintln!(
            "tuc: unexpected arguments: {:?}\nTry 'tuc --help' for more information.",
            raw.remaining
        );
        exit(1);
    } else if raw.remaining.len() == 1 {
        match raw.remaining[0].to_str() {
            Some(s) if s.starts_with('-') => {
                eprintln!(
                    "tuc: unexpected arguments: {:?}\nTry 'tuc --help' for more information.",
                    raw.remaining
                );
                exit(1);
            }
            Some(s) => Some(s.to_string()),
            None => None,
        }
    } else {
        None
    };

    if let Some(p) = &path {
        let pp = Path::new(p);
        if !pp.exists() {
            runtime_error(&format!("The file \"{p}\" does not exist"));
        }
        if !pp.is_file() {
            runtime_error(&format!("The path \"{p}\" is not a file"));
        }
    }

    let cfg = match build_config(&raw) {
        Ok(c) => c,
        Err(m) => runtime_error(&m),
    };

    let data = match read_input(&path, raw.no_mmap) {
        Ok(d) => d,
        Err(m) => {
            eprintln!("Error: {m}");
            exit(1);
        }
    };

    let stdout = io::stdout();
    let mut out = io::LineWriter::new(stdout.lock());
    match cut::process(&cfg, &data, &mut out) {
        Ok(()) => {
            if let Err(e) = out.flush() {
                eprintln!("Error: {e}");
                exit(1);
            }
        }
        Err(ProcError::Msg(m)) => {
            let _ = out.flush();
            eprintln!("Error: {m}");
            exit(1);
        }
    }
}
RS
