/// Print a message that looks like a Rust panic and abort, matching
/// the observable behaviour of the original program in the unlikely
/// corner cases where it panics.
pub fn panic_abort(location: &str, message: &str) -> ! {
    let pid = std::process::id();
    let stderr = io::stderr();
    let mut lock = stderr.lock();
    let _ = write!(
        lock,
        "\nthread 'main' ({pid}) panicked at {location}:\n{message}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
    );
    let _ = lock.flush();
    std::process::abort();
}

pub fn panic_count_fields() -> ! {
