    let bounds: &BoundsList = if cfg.complement {
        match cfg.bounds.complemented_checked(n) {
            Ok(b) => {
                comp = b;
                &comp
            }
            Err(ComplementError::Oob) => return FailKind::Oob,
            Err(ComplementError::Empty) => return FailKind::Other,
        }
    } else {
        &cfg.bounds
    };
    if cfg.json {
        let generic = generic_active(bounds);
        for flat in &bounds.flat {
            let is_range =
                matches!(&flat.bound.kind, BoundKind::Range(_, _) if !flat.bound.is_point_range());
            if is_range {
                if !check_generic_range(&flat.bound, n) {
                    return FailKind::Oob;
                }
            } else {
                let side = match &flat.bound.kind {
                    BoundKind::Single(s) => s.clone(),
                    _ => flat.bound.point_side().expect("point bound"),
                };
                let idx = side.resolve(n);
                if idx < 1 || idx > n as i128 {
                    if generic {
                        return FailKind::Oob;
                    }
                    if fallback_for(cfg, &flat.bound).is_none() {
                        return FailKind::Oob;
                    }
                }
            }
        }
        return FailKind::None;
    }
    let mut sink: Vec<u8> = Vec::new();
    match render_flat(
        &mut sink,
        cfg,
        bounds,
        cfg.join_enabled(),
        &cfg.fields_join_delim(),
        false,
        &mut |b: &UserBound| field_segment(cfg, infos, b),
    ) {
        Ok(()) => FailKind::None,
        Err(ProcError::Msg(m)) => {
            if m.starts_with("Out of bounds") {
                FailKind::Oob
            } else {
                FailKind::Other
            }
        }
    }
}

