"""/// A range with a negative side and a multi-byte literal delimiter:
/// each endpoint is located by scanning from its own side of the
/// line, and the segment is the text between those offsets.
fn mixed_range_segment(
    cfg: &Config,
    infos: &FieldInfos,
    bound: &UserBound,
    counted: bool,
) -> PResult<Vec<u8>> {
    let (left, right) = match &bound.kind {
        BoundKind::Range(l, r) => (l, r),
        _ => unreachable!(),
    };
    let line = infos.left.line;
    // Left endpoint.
    let l_frame = if left.as_ref().map_or(false, |s| s.is_end()) {
        &infos.right
    } else {
        &infos.left
    };
    let ln = l_frame.len();
    let l = left.as_ref().map_or(1, |s| s.resolve(ln));
    if l < 1 || l > ln as i128 {
        let disp = left
            .as_ref()
            .map_or_else(|| "1".to_string(), |s| s.display());
        return oob_or_fallback(cfg, bound, format!("Out of bounds: {disp}"));
    }
    let start_off = l_frame.starts[(l - 1) as usize];
    // Right endpoint.
    let (r_idx_frame_len, end_off) = match right {
        None => (infos.left.len(), line.len()),
        Some(rside) => {
            let r_frame = if rside.is_end() {
                &infos.right
            } else {
                &infos.left
            };
            let rn = r_frame.len();
            let r = rside.resolve(rn);
            if counted {
                if r < 1 || r > rn as i128 {
                    return oob_or_fallback(cfg, bound, oob_err(rside));
                }
            } else if r > rn as i128 {
                return oob_or_fallback(cfg, bound, oob_err(rside));
            }
            let r_clamped = if r < 1 { 1 } else { r };
            (rn, r_frame.ends[(r_clamped - 1) as usize])
        }
    };
    let _ = r_idx_frame_len;
    if start_off > end_off {
        return oob_or_fallback(
            cfg,
            bound,
            "Field left value cannot be greater than right value".to_string(),
        );
    }
    Ok(transform_replace(cfg, &line[start_off..end_off]))
}

// ---------- generic (chars / JSON) range handling ----------""")
