"""fn regex_matches(re: &Regex, line: &[u8]) -> Vec<(usize, usize)> {
    // Matches the iterator semantics of regex::bytes::Regex::find_iter:
    // after an empty match the search advances by one byte, and an
    // empty match located exactly at the end of the previous match
    // is skipped.
    let mut out = Vec::new();
    let mut pos = 0usize;
    let mut last_match_end: Option<usize> = None;
    while pos <= line.len() {
        let m = match re.find_at(line, pos) {
            Some(m) => m,
            None => break,
        };
        if m.start() == m.end() {
            pos = m.end() + 1;
            if last_match_end == Some(m.end()) {
                continue;
            }
            last_match_end = Some(m.end());
            out.push((m.start(), m.end()));
        } else {
            last_match_end = Some(m.end());
            pos = m.end();
            out.push((m.start(), m.end()));
        }
    }
    out
}""")
