/// Lines mode when the bounds cannot be streamed: every
/// EOL-separated record of the input is cut as text delimited by
/// '\\n' (like the ordinary fields extractor, in its counted form).
fn process_lines_records(cfg: &Config, data: &[u8], out: &mut dyn Write) -> PResult<()> {
