    // the fields extractor applied to a record.
    let mut seg_cfg = cfg.clone();
    seg_cfg.delimiter = b"\\n".to_vec();
    seg_cfg.regex = None;
    seg_cfg.compress = false;
    seg_cfg.only_delimited = false;
    seg_cfg.json = false;
    seg_cfg.fixed_memory = None;

