        Some(r) => r.clone(),
        None => vec![b'\\n'],
    };

    for record in split_lines(data, cfg.eol()) {
        if record.is_empty() {
            if cfg.only_delimited {
                continue;
            }
            w_eol(cfg, out)?;
            continue;
        }
        let info = lines_record_info(cfg, record);
        let infos = FieldInfos {
            left: info.clone(),
            right: info,
        };
        let n = infos.left.len();
        let comp;
        let bounds: &BoundsList = if cfg.complement {
            match cfg.bounds.complemented_checked(n) {
                Ok(b) => {
                    comp = b;
                    &comp
                }
                Err(ComplementError::Oob) => {
                    if cfg.only_delimited {
                        crate::panic_count179();
                    }
                    crate::panic_count_fields();
                }
                Err(ComplementError::Empty) => {
                    if cfg.only_delimited && n <= 1 {
                        continue;
                    }
                    return err_msg("the complement is empty".to_string());
                }
            }
        } else {
            &cfg.bounds
