    fn write_segment(
        &mut self,
        out: &mut dyn Write,
        indices: &[usize],
        continuation: bool,
    ) -> PResult<()> {
        if indices.is_empty() {
            return Ok(());
        }
        let first = indices[0];
        if let Some(prev) = self.last {
            if first == prev + 1 {
                if continuation {
                    if let Some(rep) = &self.cfg.replace {
                        w(out, rep)?;
                    } else {
                        let s = self.info.ends[prev - 1];
                        let e = self.info.starts[first - 1];
                        w(out, &self.info.line[s..e])?;
                    }
                } else if self.cfg.join_enabled() {
                    w(out, &self.cfg.fields_join_delim())?;
                }
            } else if first > prev + 1 && self.cfg.join_enabled() {
                w(out, &self.cfg.fields_join_delim())?;
            }
        } else if self.cfg.join_enabled() && first > 1 {
            w(out, &self.cfg.fields_join_delim())?;
        }
        for (k, idx) in indices.iter().enumerate() {
            if k > 0 {
                if let Some(rep) = &self.cfg.replace {
                    w(out, rep)?;
                } else {
                    let s = self.info.ends[idx - 2];
                    let e = self.info.starts[idx - 1];
                    w(out, &self.info.line[s..e])?;
                }
            }
            w(out, self.info.text(*idx))?;
        }
        self.last = Some(*indices.last().unwrap());
        Ok(())
    }

    fn write_fallback(&mut self, out: &mut dyn Write, bound: &UserBound) -> PResult<bool> {
        if let Some(fb) = fallback_for(self.cfg, bound) {
            let fb = fb.to_vec();
            w(out, &fb)?;
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn process_bound(&mut self, out: &mut dyn Write, bound: &UserBound) -> PResult<()> {
        let n = self.info.len() as i128;
        match &bound.kind {
            BoundKind::Single(side) => {
                let idx = side.resolve(self.info.len());
                if idx < self.cursor || idx > n {
                    if !self.write_fallback(out, bound)? {
                        return err_msg(oob_err(side));
                    }
                } else {
                    self.write_segment(out, &[idx as usize], false)?;
                    self.cursor = idx + 1;
                }
                Ok(())
            }
            BoundKind::Range(left, right) => {
                let l = left.as_ref().map_or(1, |s| s.resolve(self.info.len()));
                match right {
                    None => {
                        let start = std::cmp::max(l, self.cursor);
                        if start <= n {
                            let indices: Vec<usize> =
                                (start..=n).map(|i| i as usize).collect();
                            let cont = start > l;
                            self.write_segment(out, &indices, cont)?;
                            self.cursor = n + 1;
                        }
                        Ok(())
                    }
                    Some(rside) => {
                        let r = rside.resolve(self.info.len());
                        if l > n {
                            if !self.write_fallback(out, bound)? {
                                let disp = left
                                    .as_ref()
                                    .map_or_else(|| "1".to_string(), |s| s.display());
                                return err_msg(format!("Out of bounds: {disp}"));
                            }
                            return Ok(());
                        }
                        let start = std::cmp::max(l, self.cursor);
                        let end = std::cmp::min(r, n);
                        if start > end {
                            if !self.write_fallback(out, bound)? {
                                let disp = left
                                    .as_ref()
                                    .map_or_else(|| "1".to_string(), |s| s.display());
                                return err_msg(format!("Out of bounds: {disp}"));
                            }
                            return Ok(());
                        }
                        let indices: Vec<usize> =
                            (start..=end).map(|i| i as usize).collect();
                        let cont = start > l;
                        self.write_segment(out, &indices, cont)?;
                        self.cursor = std::cmp::max(self.cursor, end + 1);
                        if r > n {
                            if !self.write_fallback(out, bound)? {
                                let disp = left
                                    .as_ref()
                                    .map_or_else(|| "1".to_string(), |s| s.display());
                                return err_msg(format!("Out of bounds: {disp}"));
                            }
                        }
                        Ok(())
                    }
                }
            }
        }
    }
}

