    out.write_all(bytes).map_err(|e| {
        if e.kind() == std::io::ErrorKind::BrokenPipe {
            ProcError::BrokenPipe
        } else {
            ProcError::Msg(e.to_string())
        }
    })
}""")
open("src/cut.rs","w").write(s)

