"""    match cut::process(&cfg, &data, &mut out) {
        Ok(()) => {
            if let Err(e) = out.flush() {
                if e.kind() == io::ErrorKind::BrokenPipe {
                    exit(0);
                }
                eprintln!("Error: {e}");
                exit(1);
            }
        }
        Err(ProcError::BrokenPipe) => {
            exit(0);
        }
        Err(ProcError::Msg(m)) => {
            let _ = out.flush();
            eprintln!("Error: {m}");
            exit(1);
        }
    }""")
open("src/main.rs","w").write(s)
print("ok")
